+const form = document.querySelector("#support-form");
+const statusMessage = document.querySelector("#form-status");
+
+const fields = {
+  fullName: {
+    input: document.querySelector("#full-name"),
+    error: document.querySelector("#full-name-error"),
+    validate(value) {
+      if (!value.trim()) {
+        return "Enter your full name.";
+      }
+
+      return "";
+    },
+  },
+  email: {
+    input: document.querySelector("#email"),
+    error: document.querySelector("#email-error"),
+    validate(value) {
+      const trimmedValue = value.trim();
+
+      if (!trimmedValue) {
+        return "Enter your email address.";
+      }
+
+      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)) {
+        return "Enter an email address in the format name@example.com.";
+      }
+
+      return "";
+    },
+  },
+  phone: {
+    input: document.querySelector("#phone"),
+    error: document.querySelector("#phone-error"),
+    validate(value) {
+      const trimmedValue = value.trim();
+
+      if (!trimmedValue) {
+        return "";
+      }
+
+      if (!/^\+?[\d\s().-]{7,20}$/.test(trimmedValue)) {
+        return "Enter a phone number using digits, spaces, dashes, or parentheses.";
+      }
+
+      return "";
+    },
+  },
+};
+
+function setFieldError(field, message) {
+  field.error.textContent = message;
+
+  if (message) {
+    field.input.setAttribute("aria-invalid", "true");
+  } else {
+    field.input.removeAttribute("aria-invalid");
+  }
+}
+
+function validateField(field) {
+  const message = field.validate(field.input.value);
+  setFieldError(field, message);
+  return message;
+}
+
+Object.values(fields).forEach((field) => {
+  field.input.addEventListener("blur", () => {
+    validateField(field);
+  });
+
+  field.input.addEventListener("input", () => {
+    if (field.input.getAttribute("aria-invalid") === "true") {
+      validateField(field);
+    }
+
+    statusMessage.textContent = "";
+  });
+});
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+  statusMessage.textContent = "";
+
+  const firstInvalidField = Object.values(fields).find((field) => validateField(field));
+
+  if (firstInvalidField) {
+    firstInvalidField.input.focus();
+    return;
+  }
+
+  form.reset();
+  statusMessage.textContent = "Thanks. Your support request is ready to send.";
+});
*** End Patch
